"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[49161],{49161:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/cursed-bunny.png\\"\\n          title=\\"Cursed Bunny\\"\\n          author=\\"Bora Chung\\"\\n          publisher=\\"Arzak\\"\\n          publishedDate=\\"2022-04-01\\"\\n          isbn=\\"9791166686665\\"\\n          rating=3.5\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\nA book I bought because of the advertisement that it was a ```2022 Booker Prize finalist```.  \\nIt\'s a collection of short stories by a somewhat unfamiliar Korean author, and all 10 works are abstruse and fresh. I\'m not sure whether to call it horror or SF...  \\n<br>\\nIt takes some time to read and think about each work.  \\nI\'d especially like to list the table of contents of this book here.  \\n<br>\\n```txt\\n1. Cursed Bunny\\n2. The Head\\n3. The Cold Finger\\n4. Embodiment\\n5. Goodbye, My Love\\n6. The Snare\\n7. Scars\\n8. Home Sweet Home\\n9. Ruler of the Winds and Sands\\n10. Reunion\\n```"}')}}]);